A pixel-wide gap appears between adjacent nodes at certain node sizes.

The same gap appears vertically if you modify the example to reverse the flex-direction.

comments:
```rust
use taffy::prelude::*;

fn main() {
    for width in [963.3333, 1000.] {
        example(width);
    }
}

fn example(width: f32) {
    let parent_style = Style {
        justify_content: JustifyContent::Center,
        size: Size::from_points(width, 100.),
        ..Default::default()
    };

    let child_style = Style {
        size: Size { width: Dimension::Points(100.3), height: Dimension::Auto },
        ..Default::default()
    };
    
    let mut taffy = Taffy::new();
    let children = [
        taffy.new_leaf(child_style).unwrap(),
        taffy.new_leaf(child_style).unwrap(),
    ];
    let parent = taffy.new_with_children(parent_style, &children).unwrap();

    taffy.compute_layout(parent, Size::MAX_CONTENT).ok();

    println!("Width = {width}");
    println!("parent size: {:#?}", taffy.layout(parent).unwrap().size);
    for child in children {
        println!("child layout: {:#?}", taffy.layout(child).unwrap());
    }
    println!();
}
```

